<template>  <div class="file-path">文件路径：{{ filePath }}</div>  <n-divider />  <div class="ocr-container">    <div class="ocr-text-container">      <n-input v-model:value="imageText"               type="textarea"               rows="5"               class="ocr-text"      >        <template #suffix>          <svg t="1767750657927" class="copy-icon" viewBox="0 0 1024 1024" version="1.1"               xmlns="http://www.w3.org/2000/svg"               p-id="5135" @click="copyText">            <path d="M96.1 575.7a32.2 32.1 0 1 0 64.4 0 32.2 32.1 0 1 0-64.4 0Z" p-id="5136"></path>            <path                d="M742.1 450.7l-269.5-2.1c-14.3-0.1-26 13.8-26 31s11.7 31.3 26 31.4l269.5 2.1c14.3 0.1 26-13.8 26-31s-11.7-31.3-26-31.4zM742.1 577.7l-269.5-2.1c-14.3-0.1-26 13.8-26 31s11.7 31.3 26 31.4l269.5 2.1c14.3 0.2 26-13.8 26-31s-11.7-31.3-26-31.4z"                p-id="5137"></path>            <path                d="M736.1 63.9H417c-70.4 0-128 57.6-128 128h-64.9c-70.4 0-128 57.6-128 128v128c-0.1 17.7 14.4 32 32.2 32 17.8 0 32.2-14.4 32.2-32.1V320c0-35.2 28.8-64 64-64H289v447.8c0 70.4 57.6 128 128 128h255.1c-0.1 35.2-28.8 63.8-64 63.8H224.5c-35.2 0-64-28.8-64-64V703.5c0-17.7-14.4-32.1-32.2-32.1-17.8 0-32.3 14.4-32.3 32.1v128.3c0 70.4 57.6 128 128 128h384.1c70.4 0 128-57.6 128-128h65c70.4 0 128-57.6 128-128V255.9l-193-192z m0.1 63.4l127.7 128.3H800c-35.2 0-64-28.8-64-64v-64.3h0.2z m64 641H416.1c-35.2 0-64-28.8-64-64v-513c0-35.2 28.8-64 64-64H671V191c0 70.4 57.6 128 128 128h65.2v385.3c0 35.2-28.8 64-64 64z"                p-id="5138"></path>          </svg>        </template>      </n-input>    </div>    <n-divider />    <img        :src="convertFileSrc(filePath)"        width="100%"        alt="图片加载失败"        class="ocr-img"/>  </div></template><script setup lang="ts">import {onMounted, onUnmounted, ref} from "vue";import {convertFileSrc, invoke} from "@tauri-apps/api/core";import {listen} from "@tauri-apps/api/event";import {NInput, useMessage, NDivider} from 'naive-ui';const message = useMessage();const filePath = ref('');const imageText = ref('');/** * 初始化文件更新监听器 */let reloadFilePathListener: any = null;async function initReloadFilePathListener() {  return await listen('reload-ocr-preview', async (event: any) => {    console.log("加载新的ocr图片", event.payload);    filePath.value = event.payload.filePath;    // 更新窗口url    window.history.replaceState(null, '', `${window.location.origin}${window.location.pathname}?pluginId=ocr&filePath=${encodeURIComponent(filePath.value)}`);    loadImageText();  });}/** * 加载图片文字 */async function loadImageText() {  const result = await invoke("invoke_external_plugin", {    pluginId: "ocr",    pluginName: "ocr_plugin.exe",    cmd: "ocr",    payload: JSON.stringify({filePath: filePath.value})  }) as string;  console.log("图片识别结果：", result);  if (result && result.includes("result")) {    const json = JSON.parse(result);    if (json.result) {      imageText.value = json.result;      return;    }  }  imageText.value = "图片识别失败";}async function copyText() {  await invoke("write_to_clipboard", {content: imageText.value, format: 'text'});  message.success("已复制到剪贴板");}onMounted(async () => {  const searchParams = new URLSearchParams(window.location.search);  filePath.value = <string>searchParams.get('filePath');  console.log("OCR图片路径：", filePath.value)  // 初始化文件更新监听器  reloadFilePathListener = await initReloadFilePathListener();  loadImageText();})onUnmounted(() => {  // 销毁文件更新监听器  if (reloadFilePathListener) {    reloadFilePathListener();  }})</script><style>.file-path {  padding: 5px;}.ocr-container {  width: 100%;  height: 100%;}.ocr-text-container {  padding: 2%;}.copy-icon {  width: 20px;  height: 20px;  fill: var(--theme-universal-text) !important;  opacity: 0.6;  margin-bottom: 5px;  cursor: pointer;}.copy-icon:hover {  opacity: 0.8;}.ocr-img {  object-fit: cover;  margin: 2%;  width: 96%;}</style>